'use client'

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

export type BadgeTone = 'neutral' | 'brand' | 'sky' | 'green' | 'amber' | 'red' | 'fuchsia' | 'plum'

/**
 * Badge, 1:1 with the uiKit `Badge` set (988:20203): eight tones, Large (8 × 4 padding, 24
 * high) or Small (6 × 2, 20 high), Soft (tone fill), Plain (no fill) or Outline (bg/card with a border/default edge), radius-sm or full.
 * Label medium 13/16, icon 14px in the tone colour, 4px apart. No border, no shadow.
 * The tone comes from `data-tone`, which repoints the `tone/*` tokens.
 */
const badgeVariants = cva(
  [
    'sa:inline-flex sa:shrink-0 sa:items-center sa:gap-1 sa:text-sm sa:leading-4 sa:font-medium sa:tracking-normal sa:whitespace-nowrap sa:text-tone-fg',
    'sa:[&_svg]:pointer-events-none sa:[&_svg]:size-icon-size-sm sa:[&_svg]:shrink-0 sa:[&_svg]:[stroke-width:1.875]',
  ],
  {
    variants: {
      size: {
        lg: 'sa:px-2 sa:py-1',
        sm: 'sa:px-1.5 sa:py-0.5',
      },
      variant: {
        soft: 'sa:bg-tone-bg',
        plain: 'sa:bg-transparent',
        // White (bg/card) inside a 1px border/default edge, drawn inset so the size stays put.
        outline: 'sa:bg-bg-card sa:[box-shadow:inset_0_0_0_1px_var(--sa-border-default)]',
      },
      shape: {
        default: 'sa:rounded-sm',
        rounded: 'sa:rounded-pill',
      },
    },
    defaultVariants: { size: 'lg', variant: 'soft', shape: 'default' },
  },
)

export interface BadgeProps extends React.ComponentProps<'span'>, VariantProps<typeof badgeVariants> {
  tone?: BadgeTone
}

export function Badge({ className, tone = 'neutral', size, variant, shape, ...props }: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-tone={tone}
      className={cn(badgeVariants({ size, variant, shape }), className)}
      {...props}
    />
  )
}

export { badgeVariants }
